def find_array(n, s, k):
    # Check if it's possible to construct such an array
    if k < 0 or k > n * (n - 1) // 2:
        return -1
    if k > s:
        return -1

    # Initialize the array with zeros
    A = [0] * n

    # Try to find the lexicographically smallest array
    for i in range(n):
